import { useState, useEffect } from 'react';
const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');
const gc = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':g==='C'?'#d97706':'#6b7280';

export default function Analytics({ store }) {
  const [data,    setData]    = useState(null);
  const [loading, setLoading] = useState(true);
  const [last,    setLast]    = useState(null);

  useEffect(() => { load(); const t=setInterval(load,30000); return ()=>clearInterval(t); }, []);

  const apiFetch = async path => { const r=await fetch(`${API}${path}`,{headers:{Authorization:`Bearer ${getToken()}`}}); return r.json(); };

  const load = async () => {
    try {
      const d = await apiFetch('/analytics');
      const exams = d?.exams||[], subs = d?.submissions||[];
      const results = subs.filter(s=>s.total_score!==null);
      const avg = results.length?(results.reduce((a,r)=>a+Number(r.total_score),0)/results.length).toFixed(1):0;
      const pass = results.length?Math.round(results.filter(r=>r.grade&&r.grade!=='F').length/results.length*100):0;
      const fail = results.length - Math.round(pass/100*results.length);
      const unique = new Set(subs.map(s=>s.student_id)).size;
      setData({ exams, subs, results, avg, pass, fail, unique });
      setLast(new Date());
    } catch(e) { console.error(e); }
    finally { setLoading(false); }
  };

  const STAT_CARDS = data ? [
    { label:'TOTAL SUBMISSIONS', value:data.subs.length,   sub:`${data.unique} unique students`, color:'#6d28d9' },
    { label:'AVERAGE SCORE',     value:data.avg,            sub:'Across all exams',               color:'#16a34a' },
    { label:'PASS RATE',         value:`${data.pass}%`,     sub:`${Math.round(data.pass/100*(data.results.length||1))} passed · ${data.fail} failed`, color:'#2563eb' },
    { label:'YOUR EXAMS',        value:data.exams.length,   sub:`High: ${data.exams.length} · Low: 0`, color:'#d97706' },
  ] : [];

  const gradeGroups = data ? data.results.reduce((acc,r)=>{ const g=r.grade||'F'; acc[g]=(acc[g]||0)+1; return acc; },{}) : {};

  return (
    <div className="fade-up">
      {/* Header — matches Image 5 */}
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:20 }}>
        <div>
          <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a', marginBottom:4 }}>Analytics Dashboard</h1>
          <p style={{ fontSize:12, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace' }}>
            Auto-updates every 30 seconds · {data?.subs?.length||0} submissions recorded
          </p>
        </div>
        <button onClick={load} style={{ display:'flex', alignItems:'center', gap:8, padding:'8px 18px', background:'#fff', border:'1px solid #e5e7eb', borderRadius:10, fontWeight:600, fontSize:13, color:'#374151', cursor:'pointer' }}>
          <span style={{ fontSize:14 }}>🔄</span> Refresh
        </button>
      </div>

      {/* 4 stat cards — matches Image 5 with colored top borders */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:20 }}>
        {STAT_CARDS.map((s,i) => (
          <div key={i} style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:12, padding:'18px 20px', position:'relative', overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ position:'absolute', top:0, left:0, right:0, height:3, background:s.color }}/>
            <div style={{ fontSize:10, fontWeight:700, textTransform:'uppercase', letterSpacing:1.5, color:'#9ca3af', marginBottom:12, fontFamily:'JetBrains Mono,monospace' }}>{s.label}</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:28, color:'#0f0f1a', lineHeight:1, marginBottom:8 }}>{s.value}</div>
            <div style={{ fontSize:12, color:'#9ca3af' }}>{s.sub}</div>
          </div>
        ))}
      </div>

      {/* Main content area */}
      <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
        {loading ? (
          <div style={{ display:'flex', alignItems:'center', gap:12, padding:60, justifyContent:'center' }}>
            <div className="spinner" style={{width:28,height:28}}/><span style={{color:'#6b7280',fontSize:14}}>Loading analytics...</span>
          </div>
        ) : !data || data.subs.length === 0 ? (
          /* Empty state matches Image 5 */
          <div style={{ textAlign:'center', padding:'60px 24px' }}>
            <div style={{ fontSize:52, marginBottom:14, opacity:.25 }}>📊</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:18, color:'#374151', marginBottom:8 }}>No submissions yet</div>
            <div style={{ fontSize:13, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace' }}>Analytics will appear once students start submitting exams</div>
          </div>
        ) : (
          <div style={{ padding:24 }}>
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:24 }}>
              {/* Grade distribution */}
              <div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a', marginBottom:16 }}>Grade Distribution</div>
                {['A+','A','B','C','D','F'].map(grade => {
                  const count = gradeGroups[grade]||0;
                  const pct   = data.results.length ? Math.round(count/data.results.length*100) : 0;
                  const color = gc(grade);
                  return (
                    <div key={grade} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
                      <span style={{ width:28, textAlign:'center', fontFamily:'JetBrains Mono,monospace', fontWeight:800, fontSize:12, color, flexShrink:0 }}>{grade}</span>
                      <div style={{ flex:1, height:8, background:'#f3f4f6', borderRadius:4, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${pct}%`, background:`linear-gradient(90deg,${color}88,${color})`, borderRadius:4, transition:'width .8s' }}/>
                      </div>
                      <span style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', width:48, textAlign:'right' }}>{count} ({pct}%)</span>
                    </div>
                  );
                })}
              </div>

              {/* Per-exam performance */}
              <div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a', marginBottom:16 }}>Per Exam Performance</div>
                {data.exams.slice(0,6).map(exam => {
                  const examSubs = data.results.filter(r=>r.exam_id===exam.exam_id);
                  const avgPct = examSubs.length ? Math.round(examSubs.reduce((a,r)=>a+Number(r.total_score)/Number(r.total_marks)*100,0)/examSubs.length) : 0;
                  return (
                    <div key={exam.exam_id} style={{ marginBottom:10 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', marginBottom:4 }}>
                        <span style={{ fontSize:12, fontWeight:600, color:'#374151' }}>{exam.title?.slice(0,24)}{exam.title?.length>24?'…':''}</span>
                        <span style={{ fontSize:11, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace', fontWeight:700 }}>{examSubs.length} sub · {avgPct}%</span>
                      </div>
                      <div style={{ height:6, background:'#f3f4f6', borderRadius:3, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${avgPct}%`, background:'#7c3aed', borderRadius:3, transition:'width .8s' }}/>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Recent submissions table */}
            <div style={{ marginTop:24, borderTop:'1px solid #f3f4f6', paddingTop:20 }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a', marginBottom:14 }}>Recent Submissions</div>
              <table style={{ width:'100%', borderCollapse:'collapse' }}>
                <thead><tr style={{ background:'#f8f8fc' }}>
                  {['STUDENT','EXAM','SCORE','GRADE','DATE'].map(h=><th key={h} style={{padding:'9px 16px',textAlign:'left',fontSize:9,fontWeight:700,color:'#9ca3af',textTransform:'uppercase',letterSpacing:1.5,fontFamily:'JetBrains Mono,monospace',borderBottom:'1px solid #f3f4f6'}}>{h}</th>)}
                </tr></thead>
                <tbody>
                  {data.results.slice(0,8).map((r,i) => {
                    const color = gc(r.grade);
                    return (
                      <tr key={i} style={{borderBottom:'1px solid #f3f4f6'}} onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                        <td style={{padding:'11px 16px',fontWeight:600,color:'#0f0f1a',fontSize:13}}>{r.student_name||'—'}</td>
                        <td style={{padding:'11px 16px',fontSize:12,color:'#6b7280'}}>{r.exam_title?.slice(0,20)||'—'}</td>
                        <td style={{padding:'11px 16px',fontFamily:'JetBrains Mono,monospace',fontSize:12,fontWeight:700,color:'#374151'}}>{Number(r.total_score).toFixed(0)}/{r.total_marks}</td>
                        <td style={{padding:'11px 16px'}}><span style={{padding:'2px 8px',borderRadius:4,background:`${color}15`,color,fontSize:10,fontWeight:800}}>{r.grade}</span></td>
                        <td style={{padding:'11px 16px',fontSize:11,color:'#9ca3af',fontFamily:'JetBrains Mono,monospace'}}>{r.submit_time?new Date(r.submit_time).toLocaleDateString():'-'}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
      {last && <div style={{ marginTop:10, fontSize:11, color:'#9ca3af', textAlign:'right', fontFamily:'JetBrains Mono,monospace' }}>Last updated: {last.toLocaleTimeString()}</div>}
    </div>
  );
}
